from pathlib import Path
import struct,json,math,hashlib
import numpy as np
p=Path(__file__).resolve().parent;base=p.parent;capture=base/'rain-coupled-anchor-audit/baseline';phase=base/'rain-hip-phase-replay/ordinary-on'
assert (capture/'state.txt').read_bytes()==(phase/'state.txt').read_bytes()
assert json.loads((capture/'exit.json').read_text())['exit']==0
assert json.loads((phase/'exit.json').read_text())['exit']==0
f=lambda x:struct.unpack('!f',bytes.fromhex(x))[0]
v=lambda x:np.array([f(t) for t in x])
def R(q):
 x,y,z,w=q;return np.array([[1-2*(y*y+z*z),2*(x*y-z*w),2*(x*z+y*w)],[2*(x*y+z*w),1-2*(x*x+z*z),2*(y*z-x*w)],[2*(x*z-y*w),2*(y*z+x*w),1-2*(x*x+y*y)]])
def mul(a,b):return np.r_[a[3]*b[:3]+b[3]*a[:3]+np.cross(a[:3],b[:3]),a[3]*b[3]-np.dot(a[:3],b[:3])]
def inv(q):return np.r_[-q[:3],q[3]]
def S(r):
 x,y,z=r;return np.array([[0,-z,y],[z,0,-x],[-y,x,0]])
def twist(q):return 2*math.atan2(q[2] if q[3]>=0 else -q[2],abs(q[3]))
def swing(q):return 2*math.atan2(np.linalg.norm(q[:2]),np.linalg.norm(q[2:]))
def soften(h,hz,damp):
 omega=2*math.pi*hz;a1=2*damp+h*omega;a2=h*omega*a1;return omega/a1,1/a2
# Exact torque-ball reference for the block residual; independent eigensolver.
def ball(K,g,r):
 if r==0:return np.zeros(3)
 e,V=np.linalg.eigh(K);z=V.T@g;x=-V@(z/e)
 if np.linalg.norm(x)<=r:return x
 low=0.;high=np.linalg.norm(g)/r
 for _ in range(64):
  mid=.5*(low+high)
  if np.linalg.norm(z/(e+mid))>r:low=mid
  else:high=mid
 return -V@(z/(e+high))
def block(A,I,w,lam,bias,gamma=0,domain='free',cap=0):
 A=np.atleast_2d(A);lam=np.atleast_1d(lam);bias=np.atleast_1d(bias)
 K=A@I@A.T;K=(K+K.T)/2;assert min(np.linalg.eigvalsh(K))>0
 H=(1+gamma)*K;r=A@w+bias+gamma*K@lam
 if domain=='ball':new=ball(H,r-H@lam,cap)
 else:
  new=lam-np.linalg.solve(H,r)
  if domain=='positive':new=np.maximum(new,0)
  if domain=='box':new=np.clip(new,-cap,cap)
 delta=new-lam;gap=float(-r@delta-.5*delta@H@delta);assert gap>=-1e-9
 return {'gap':max(0,gap),'residual_norm':float(np.linalg.norm(r)),'impulse_correction':float(np.linalg.norm(delta))}
raw=(phase/'phases.bin').read_bytes();offset=0;rows=[];max_final_v=0.;max_finalize_change=0.;flags=set();jids=None
for line in (capture/'trace.jsonl').open():
 d=json.loads(line);frame,n=struct.unpack_from('<II',raw,offset);offset+=8;assert frame==d['frame']-1 and n==192*44
 words=np.frombuffer(raw,dtype='<u4',count=n,offset=offset);offset+=4*n;states=words.view('<f4')[192:].reshape(24,43,8);assert all(words[k*8]==k for k in range(24))
 bs={b['identity']:b for b in d['bodies']};starts=dict(zip(d['body_storage_order'],d['host_state']['step_start_bodies']));h=f(d['settings']['dt'])
 def velocity(i,ph):
  a=states[ph,i-1];return a[[0,4,1]].astype(float),a[5:8].astype(float)
 def inertia(b):
  diagonal=v(b['inv_inertia']);lo=v(b['gpu_motion']['inv_inertia_offdiag']);hi=v(b['gpu_motion']['inv_inertia_upper']);local=np.array([[diagonal[0],hi[0],hi[1]],[lo[0],diagonal[1],hi[2]],[lo[1],lo[2],diagonal[2]]]);r=R(v(starts[b['identity']]['rot']));return r@local@r.T
 for id,b in bs.items():
  if id==1:continue
  final=np.r_[*velocity(id,23)];max_final_v=max(max_final_v,float(np.max(abs(final-np.r_[v(b['vel']),v(b['omega'])]))));max_finalize_change=max(max_finalize_change,float(np.max(abs(final-np.r_[*velocity(id,21)]))));flags.add(b['flags']);assert not b['flags']&7
 joints=[j for j in d['joints'] if j['kind'] in [1,3]];assert len(joints)==39
 ids={j['identity'] for j in joints};assert jids is None or jids==ids;jids=ids
 for j in joints:
  a,b=[bs[j[k]] for k in ['a','b']];ia,ib=inertia(a),inertia(b);I=ia+ib;I=(I+I.T)/2
  va,wa=velocity(j['a'],21);vb,wb=velocity(j['b'],21);w=wb-wa
  ra,rb=[R(v(z['rot']))@(v(j['anchor_'+k])-v(z['local_center'])) for k,z in [('a',a),('b',b)]]
  Kp=(f(a['inv_mass'])+f(b['inv_mass']))*np.eye(3)-S(ra)@ia@S(ra)-S(rb)@ib@S(rb);Kp=(Kp+Kp.T)/2
  vp=vb+np.cross(wb,rb)-va-np.cross(wa,ra);delta_p=-np.linalg.solve(Kp,vp);pointgap=float(-vp@delta_p-.5*delta_p@Kp@delta_p)
  dw=ib@np.cross(rb,delta_p)+ia@np.cross(ra,delta_p)
  qa,qb=[mul(v(z['rot']),v(j['frame_'+k+'_rotation'])) for k,z in [('a',a),('b',b)]]
  qa0,qb0=[mul(v(starts[z['identity']]['rot']),v(j['frame_'+k+'_rotation'])) for k,z in [('a',a),('b',b)]]
  if j['kind']==1 and np.dot(qa,qb)<0:qb=-qb
  rel=mul(inv(qa),qb);rel0=mul(inv(qa0),qb0);z=R(qa0)[:,2];angle=twist(rel);spec=[]
  def add(name,A,lam,bias,gamma=0,domain='free',cap=0):spec.append((name,A,lam,bias,gamma,domain,cap))
  if j['kind']==3:
   zB=R(qb0)[:,2];axis=np.cross(z,zB);axis=axis/np.linalg.norm(axis) if np.linalg.norm(axis)>0 else axis
   denom=np.dot(rel0[2:],rel0[2:]);tan=np.sqrt(np.dot(rel0[:2],rel0[:2])/denom) if denom>0 else 0;twistJ=z+tan*np.cross(axis,z)
   if j['flags']&1:
    rate,gamma=soften(h,f(j['spring_hertz']),f(j['spring_damping']));target=v(j['target_rotation']);q=rel if np.dot(rel,target)>=0 else -rel;c=-R(qa)@(2*mul(target-q,inv(q))[:3]);add('spherical_spring',np.eye(3),v(j['spring_angular_impulse']),rate*c,gamma)
   if j['flags']&8:add('spherical_motor',np.eye(3),v(j['motor_angular_impulse']),-v(j['motor_angular_velocity']),0,'ball',h*f(j['max_motor_force']))
   if j['flags']&4:
    lower=angle-f(j['lower_translation']);upper=f(j['upper_translation'])-angle
    add('spherical_lower',twistJ,f(j['lower_impulse']),max(0,lower)/h,0,'positive');add('spherical_upper',-twistJ,f(j['upper_impulse']),max(0,upper)/h,0,'positive')
   if j['flags']&2:add('spherical_cone',-axis,f(j['swing_impulse']),max(0,f(j['target_translation'])-swing(rel))/h,0,'positive')
  else:
   if j['flags']&1:
    rate,gamma=soften(h,f(j['spring_hertz']),f(j['spring_damping']));add('revolute_spring',z,f(j['spring_impulse']),rate*(angle-f(j['target_translation'])),gamma)
   if j['flags']&4:add('revolute_motor',z,f(j['motor_impulse']),-f(j['motor_speed']),0,'box',h*f(j['max_motor_force']))
   if j['flags']&2:
    add('revolute_lower',z,f(j['lower_impulse']),max(0,angle-f(j['lower_translation']))/h,0,'positive');add('revolute_upper',-z,f(j['upper_impulse']),max(0,f(j['upper_translation'])-angle)/h,0,'positive')
   assert j['revolute_axes_step']==d['frame'];add('revolute_alignment',np.array([v(j['weld_linear_impulse']),v(j['weld_angular_impulse'])]),v(j['perp_impulse']),np.zeros(2))
  blocks={};after={}
  for name,A,lam,bias,gamma,domain,cap in spec:
   blocks[name]=block(A,I,w,lam,bias,gamma,domain,cap);after[name]=block(A,I,w+dw,lam,bias,gamma,domain,cap)
  rows.append({'frame':d['frame'],'joint':j['identity'],'kind':j['kind'],'a':j['a'],'b':j['b'],'point':{'gap':pointgap,'residual_norm':float(np.linalg.norm(vp))},'angular':blocks,'angular_after_point':after,'point_angular_velocity_change':float(np.linalg.norm(dw))})
assert len(rows)==4680 and offset==len(raw) and max_final_v==0
summary={}
for label,sel in [('all',rows),('tail60',[r for r in rows if r['frame']>60]),('hip_tail60',[r for r in rows if r['frame']>60 and r['joint']==36])]:
 groups={}
 for r in sel:
  for name,rr in [('point',r['point']),*r['angular'].items()]:groups.setdefault(name,[]).append(rr)
 result={name:{'count':len(rs),'mean_gap':float(np.mean([r['gap'] for r in rs])),'max_gap':max(r['gap'] for r in rs),'mean_residual_norm':float(np.mean([r['residual_norm'] for r in rs])),'max_residual_norm':max(r['residual_norm'] for r in rs)} for name,rs in groups.items()}
 result['point_counterfactual']={'angular_gap_sum_before':sum(x['gap'] for r in sel for x in r['angular'].values()),'angular_gap_sum_after':sum(x['gap'] for r in sel for x in r['angular_after_point'].values()),'worsens_count':sum(sum(x['gap'] for x in r['angular_after_point'].values())>sum(x['gap'] for x in r['angular'].values())+1e-9 for r in sel)}
 summary[label]=result
result={'scope':'Post-final-relaxation block residuals and hypothetical isolated point correction; gaps are row-objective decreases, not additive global energy or physical acceptance. Float64 geometry reconstruction from captured state.','frames':120,'joints':39,'joint_observations':4680,'max_published_velocity_error':max_final_v,'max_phase21_to23_velocity_change':max_finalize_change,'body_flags':sorted(flags),'summary':summary,'input_sha256':{str(f):hashlib.sha256(f.read_bytes()).hexdigest() for f in [capture/'trace.jsonl',phase/'phases.bin',capture/'state.txt']}}
(p/'rows.json').write_text(json.dumps(rows));(p/'summary.json').write_text(json.dumps(result,indent=2));print(json.dumps(result,indent=2))
